 "on_enter": {
  "type": "tts",
  "text": "Hello, this is the automated assistant of Example Bank, and this call is recorded. Am I speaking with {{title}} {{last_name}}?"
 },
 "on_enter_first_entry_only": true,
 "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only a clear yes or their own name confirms it. If the answer is unclear, ask once more. Say nothing about why you are calling. Call end_call only right after you said goodbye.",
 "tools": [
  {
   "type": "function",
   "config": {
    "timeoutMs": 10000
   },
   "function": {
    "name": "end_call",
    "handler": "__function__:end_call",
    "description": "Ends the call. CALL it right after you said goodbye, with no other text.",
    "parameters": {
     "type": "object",
     "properties": {
      "message_mode": {
       "type": "string",
       "default": "none"
      }
     }
    }
   }
  }
 ],
 "extraction_schema": [
  {
   "name": "who",
   "type": "string",
   "enum_values": [
    "customer",
    "someone_else",
    "not_their_line",
    "unclear"
   ],
   "description": "Who answered: customer (clear yes or own name), someone_else, not_their_line, unclear.",
   "min_confidence": 0.6
  }
 ],
 "max_node_turns": 3,
 "max_turn_transition": "goodbye_short",
 "transitions": [
  {
   "target_node": "identity",
   "description": "The customer confirmed",
   "condition": {
    "logic": "or",
    "conditions": [
     {
      "variable": "who",
      "operator": "equals",
      "operand": "customer"
     }
    ]
   }
  },
  {
   "target_node": "third_party_prep",
   "description": "Someone else answered",
